NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Galatians'

CHAPTERS = {
    1: {
        1: 'Pavel, apostol (ne od ljudi niti ne po človeku, temveč po Jezusu Kristusu in Bogu Očetu, ki ga je obudil od mrtvih)',
        2: 'in vsi bratje, ki so z menoj, cerkvam v Galatiji:',
        3: '›Milost bodi vam in mir od Boga Očeta in od našega Gospoda Jezusa Kristusa,',
        4: 'ki je samega sebe dal za naše grehe, da nas lahko osvobodi iz tega sedanjega hudobnega sveta, glede na voljo Boga in našega Očeta,',
        5: 'ki mu bodi slava na veke vekov. Amen.‹',
        6: 'Čudim se, da ste se tako hitro oddaljili od tistega, ki vas je poklical v Kristusovo milost, k drugemu evangeliju,',
        7: 'ki ni drug, temveč so tam nekateri, ki vas vznemirjajo in hočejo izkriviti Kristusov evangelij.',
        8: 'Toda čeprav vam mi ali angel iz nebes oznanja kak drug evangelij, kakor tega, ki smo vam ga oznanili, naj bo ta preklet.',
        9: 'Kakor smo rekli prej, tako ponovno govorim sedaj: »Če vam katerikoli človek oznani kak drug evangelij, kakor ta, ki ste ga prejeli, naj bo preklet.«',
        10: 'Kajti ali sedaj pregovarjam ljudi ali Boga? Ali poskušam ugajati ljudem? Kajti če bi še ugajal ljudem, ne bi bil Kristusov služabnik.',
        11: 'Toda potrjujem vam, bratje, da evangelij, ki je bil oznanjen po meni, ni po človeku.',
        12: 'Kajti niti ga nisem prejel od človeka niti se ga nisem naučil, temveč po razodetju Jezusa Kristusa.',
        13: 'Kajti slišali ste o mojem vedênju, v preteklem času v judovski religiji, da sem preko mere preganjal Božjo cerkev in jo pustošil,',
        14: 'in v judovski religiji napredoval nad mnoge svoje vrstnike v svojem lastnem narodu in bil še silno vnet za izročila svojih očetov.',
        15: 'Toda ko je Bogu, ki me je od maternice moje matere odbral in me poklical po svoji milosti, ugajalo,',
        16: 'da v meni razodene svojega Sina, da bi ga lahko oznanjal med pogani, se nisem takoj posvetoval z mesom in krvjo,',
        17: 'niti nisem odšel gor v Jeruzalem k tem, ki so bili apostoli pred menoj, temveč sem odšel v Arabijo in se ponovno vrnil v Damask.',
        18: 'Potem sem po treh letih odšel gor v Jeruzalem, da vidim Petra in z njim ostal petnajst dni.',
        19: 'Toda izmed apostolov nisem videl nobenega drugega, razen Jakoba, Gospodovega brata.',
        20: 'Torej stvari, ki vam jih pišem, glejte, pred Bogom, ne lažem.',
        21: 'Kasneje sem prišel v področja Sirije in Kilikije;',
        22: 'in po obrazu sem bil nepoznan cerkvam v Judeji, ki so bile v Kristusu,',
        23: 'toda samo slišali so: »Da tisti, ki nas je v preteklih časih preganjal, sedaj oznanja vero, ki jo je nekoč uničeval.«',
        24: '§ In slavili so Boga v meni.',
    },
    2: {
        1: 'Potem sem po štirinajstih letih ponovno z Barnabom odšel gor v Jeruzalem in s seboj vzel tudi Tita.',
        2: 'In gor sem odšel po razodetju in jim posredoval ta evangelij, ki ga oznanjam med pogani, toda skrivaj tem, ki so bili ugledni, da ne bi na kakršenkoli način tekel ali sem tekel zaman.',
        3: 'Toda niti Tit, ki je bil z menoj, ki je bil Grk, ni bil prisiljen, da se obreže.',
        4: 'In to zaradi nepričakovano privedenih lažnih bratov, ki so prišli na skrivnem, da zalezujejo našo svobodo, ki jo imamo v Kristusu Jezusu, da bi nas lahko privedli v suženjstvo;',
        5: 'katerim nismo niti za eno uro dali prostora s podložnostjo, da bi se evangelijska resnica lahko nadaljevala z vami.',
        6: 'Toda izmed teh, ki so se zdeli, da so nekaj (karkoli so bili, mi ni važno; Bog ne sprejema človeške zunanjosti), kajti tisti, ki so se zdeli, da so nekaj, mi na posvetovanju niso ničesar dodali,',
        7: 'temveč nasprotno, ko so videli, da je bil evangelij neobreze zaupan meni, kakor je bil evangelij obreze Petru',
        8: '(kajti, kdor je učinkovito deloval v Petru k apostolstvu obrezanih, isti je bil mogočen v meni za pogane).',
        9: 'In ko so Jakob, Kefa in Janez, ki se zdijo, da so stebri, zaznali milost, ki mi je bila dana, so meni in Barnabu podali desnice družabništva, da bi midva šla k poganom, oni pa k obrezanim.',
        10: 'Le želeli so, da bi se spominjala revnih; isto kar sem si tudi sam prizadeval storiti.',
        11: 'Toda ko je Peter prišel v Antiohijo, sem se mu v obraz uprl, ker je bil za ošteti.',
        12: 'Kajti preden so prišli nekateri od Jakoba, je jedel s pogani. Toda ko so prišli, se je umaknil in se oddvojil, ker se je bal teh, ki so bili iz obreze.',
        13: 'In prav tako so se z njim pretvarjali drugi Judje; do te mere, da je bil tudi Barnaba zapeljan z njihovim pretvarjanjem.',
        14: 'Toda ko sem videl, da niso živeli pošteno, glede na resnico evangelija, sem pred vsemi temi rekel Petru: »Če ti, ki si Jud, živiš po načinu poganov, ne pa, kakor počno Judje, zakaj siliš pogane, da živijo, kakor počno Judje?«',
        15: 'Mi, ki smo Judje po naravi, ne pa poganski grešniki,',
        16: 'vemo, da človek ni opravičen po delih postave, temveč po veri v Jezusa Kristusa, celó mi smo verovali v Jezusa Kristusa, da bi bili lahko opravičeni po veri v Kristusa, ne pa po delih postave, kajti po delih postave ne bo opravičeno nobeno meso.',
        17: 'Toda če smo, medtem ko si prizadevamo biti opravičeni po Kristusu, tudi mi sami spoznani [za] grešnike, je potemtakem Kristus služabnik greha? Bog ne daj.',
        18: 'Kajti če ponovno gradim stvari, ki sem jih uničil, samega sebe delam prestopnika.',
        19: 'Kajti po postavi sem mrtev postavi, da bi lahko živel Bogu.',
        20: 'Križan sem s Kristusom, pa vendar živim; vendar ne jaz, temveč Kristus živi v meni. In življenje, ki ga sedaj živim v mesu, živim po veri v Božjega Sina, ki me je ljubil in dal zame samega sebe.',
        21: 'Ne onemogočam Božje milosti; kajti če je pravičnost prišla po postavi, potem je Kristus umrl zaman.',
    },
    3: {
        1: '§ O nespametni Galačani, kdo vas je uročil, da ne bi ubogali resnice, pred čigar očmi je bil očitno postavljen Jezus Kristus, križan med vami?',
        2: 'Samo to hočem izvedeti od vas: »Ali ste prejeli Duha z deli postave ali s poslušnostjo veri?«',
        3: 'Ali ste tako nespametni? Ali ste, začenši z Duhom, sedaj popolni v mesu?',
        4: 'Ali ste toliko stvari pretrpeli zaman? Če bi bile vendarle zaman.',
        5: 'On torej, ki vam daje Duha in med vami dela čudeže, ali jih dela po delih postave ali po poslušnosti veri?',
        6: 'Celó kakor je Abraham veroval Bogu in mu je bilo to šteto za pravičnost.',
        7: 'Spoznajte torej, da so Abrahamovi otroci tisti, ki so iz vere.',
        8: 'In ker je pismo slutilo, da bo Bog pogane opravičil po veri, je poprej oznanjalo evangelij Abrahamu, rekoč: ›V tebi bodo blagoslovljeni vsi narodi.‹',
        9: 'Tako so torej tisti, ki so iz vere, blagoslovljeni z zvestim Abrahamom.',
        10: 'Kajti kolikor jih je iz del postave, so pod prekletstvom, kajti pisano je: ›Preklet je vsak, kdor ne vztraja v vseh stvareh, ki so pisane v knjigi postave, da jih izvrši.‹',
        11: 'Toda očitno je to, da v Božjih očeh noben človek ni opravičen s postavo, kajti: ›Pravični bo živel iz vere.‹',
        12: 'Postava pa ni iz vere, temveč: ›Človek, ki jih izvršuje, bo živel po njih.‹',
        13: 'Kristus nas je odkupil od prekletstva postave, ko je za nas postal prekletstvo, kajti pisano je: ›Preklet je vsak, kdor visi na drevesu.‹',
        14: 'Da bi Abrahamov blagoslov lahko po Jezusu Kristusu prešel na pogane, da bi mi po veri lahko prejeli obljubo Duha.',
        15: 'Bratje, govorim po človeških običajih: »Čeprav je to samo človeška zaveza, vendar če je potrjena, je noben človek ne razveljavlja ali dodaja k njej.«',
        16: 'Torej obljube so bile izrečene Abrahamu in njegovemu semenu. Ni rekel: ›In semenom,‹ kakor mnogim; temveč kakor enemu: ›In tvojemu semenu,‹ ki je Kristus.',
        17: '§ In pravim to, da zaveze, ki je bila prej potrjena od Boga v Kristusu, postava, ki je bila štiristo trideset let kasneje, ne more razveljaviti, da bi obljubo storila brez učinka.',
        18: 'Kajti če je dediščina po postavi, le-ta ni več po obljubi; toda Bog jo je Abrahamu dal po obljubi.',
        19: 'Čemu potem služi postava? Dodana je bila zaradi prestopkov, dokler ne bi prišel potomec, ki mu je bila dana obljuba; in ta je bila odrejena po angelih v roko posrednika.',
        20: 'Torej posrednik ni posrednik enega, toda Bog je eden.',
        21: 'Ali je potem postava zoper Božje obljube? Bog ne daj, kajti če bi bila dana postava, ki bi lahko dala življenje, bi bila pravičnost resnično po postavi.',
        22: 'Toda pismo je vse zaprlo pod greh, da bi bila lahko tem, ki verujejo, dana obljuba po veri Jezusa Kristusa.',
        23: 'Toda preden je prišla vera, smo bili držani pod postavo, zaprti veri, ki naj bi se razodela kasneje.',
        24: 'Zatorej je bila postava naša vzgojiteljica, da nas privede h Kristusu, da bi bili mi lahko opravičeni iz vere.',
        25: 'Toda potem, ko je prišla vera, nismo več pod vzgojiteljico.',
        26: 'Kajti vi vsi ste Božji otroci po veri v Kristusa Jezusa.',
        27: 'Kajti tako veliko, kot vas je bilo krščenih v Kristusa, ste oblekli Kristusa.',
        28: 'Ni niti Juda niti Grka, ni niti sužnja niti svobodnega, ni niti moškega niti ženske; kajti vsi vi ste eno v Kristusu Jezusu.',
        29: 'Če pa ste Kristusovi, potem ste Abrahamovo seme in dediči glede na obljubo.',
    },
    4: {
        1: 'Pravim torej: » Da se dedič, dokler je še otrok, nič ne razlikuje od služabnika, čeprav je gospodar vsega,',
        2: 'temveč je pod varuhi in vzgojitelji do časa, določenega od očeta.«',
        3: 'Točno tako smo bili mi, ko smo bili otroci, v suženjstvu pod prvinami sveta.',
        4: 'Toda ko je prišla polnost časa, je Bog poslal svojega Sina, rojenega iz ženske, postavljenega pod postavo,',
        5: 'da odkupi te, ki so bili pod postavo, da bi mi lahko prejeli posinovljenje.',
        6: 'In ker ste sinovi, je Bog v vaša srca poslal Duha svojega Sina, ki kliče: »Aba, Oče.«',
        7: '§ Zatorej nisi več služabnik, temveč sin; če pa [si] sin, [si] potem po Kristusu Božji dedič.',
        8: 'Vendar ste tedaj, ko niste poznali Boga, služili tem, ki po naravi niso bogovi.',
        9: 'Toda sedaj, potem ko ste spoznali Boga, ali bolje rečeno ste spoznani od Boga, kako se ponovno obračate k slabotnim in bednim prvinam, ki jim želite biti ponovno v suženjstvu?',
        10: 'Obeležujete dneve in mesece in čase in leta.',
        11: 'Bojim se za vas, da nisem na vas zaman priložil truda.',
        12: 'Bratje, rotim vas, bodite kakor sem jaz; kajti jaz sem kakor ste vi; sploh me niste prizadeli.',
        13: 'Vi veste, kako sem vam na začetku oznanjal evangelij iz šibkosti mesa.',
        14: '§ In moje preizkušnje, ki je bila v mojem mesu, niste niti prezirali niti zavrgli, temveč ste me sprejeli kot Božjega angela, celó kot Kristusa Jezusa.',
        15: 'Kje je potem blagoslovljenost, o kateri ste govorili? Kajti pričujem vam, da če bi bilo mogoče, bi si iztaknili lastne oči in mi jih dali.',
        16: 'Sem torej postal vaš sovražnik, ker vam govorim resnico?',
        17: 'Oni so vam goreče naklonjeni, toda ne pravilno; da, izključili bi vas, da bi jim vi bili goreče naklonjeni.',
        18: 'Toda dobro je biti nenehno goreče naklonjen v dobri stvari in ne samo, kadar sem prisoten z vami.',
        19: 'Moji majhni otroki, zaradi katerih se mučim v ponovnem rojevanju, dokler ne bo v vas oblikovan Kristus,',
        20: 'sedaj želim biti prisoten z vami in spremeniti svoj glas; kajti stojim s pomislekom o vas.',
        21: 'Povejte mi vi, ki želite biti pod postavo, ali ne slišite postave?',
        22: 'Kajti pisano je, da je imel Abraham dva sinova, enega s sužnjico, drugega pa s svobodno.',
        23: 'Toda ta, ki je bil iz sužnje, je bil rojen po mesu; toda tisti iz svobodne, je bil po obljubi.',
        24: 'Katere stvari so prispodoba, kajti to sta dve zavezi; ena z gore Sinaj, ki povzroča suženjstvo, ki je Hagára.',
        25: 'Kajti ta Hagára je gora Sinaj v Arabiji in ustreza [prestolnici] Jeruzalem, ki je sedaj in je v suženjstvu s svojimi otroki.',
        26: 'Toda [prestolnica] Jeruzalem, ki je zgoraj, je svobodna, ki je mati nas vseh.',
        27: 'Kajti pisano je: ›Veseli se, ti jalova, ki ne rojevaš; izbruhni in zavpij, ti, ki nisi v porodnih mukah; kajti zapuščena ima mnogo več otrok kakor tista, ki ima soproga.‹',
        28: 'Torej smo mi, bratje, kot je bil Izak, otroci obljube.',
        29: 'Toda kakor je takrat, kdor je bil rojen po mesu, preganjal tistega, ki je bil rojen po Duhu, točno tako je to sedaj.',
        30: 'Vendar kaj pravi pismo? ›Spôdi sužnjo in njenega sina, kajti sin sužnje ne bo dedič s sinom svobodne.‹',
        31: 'Zaradi tega, bratje, nismo otroci sužnje, temveč svobodne.',
    },
    5: {
        1: 'Stojte torej trdno v svobodi, s katero nas je Kristus osvobodil in ne bodite ponovno vpleteni z jarmom sužnosti.',
        2: 'Glejte, jaz, Pavel, vam povem, da če boste obrezani, vam Kristus ne bo nič koristil.',
        3: 'Kajti ponovno pričujem vsakemu človeku, ki je obrezan, da je dolžnik izpolnjevanja celotne postave.',
        4: 'Katerikoli izmed vas ste opravičeni po postavi, vam je Kristus postal nekoristen; odpadli ste od milosti.',
        5: 'Kajti mi po Duhu čakamo na upanje pravičnosti iz vere.',
        6: 'Kajti v Jezusu Kristusu niti obreza ne koristi nič niti neobreza, temveč vera, ki deluje po ljubezni.',
        7: 'Dobro ste tekli; kdo vas je oviral, da ne bi ubogali resnice?',
        8: 'To prepričevanje ne prihaja od tistega, ki vas kliče.',
        9: 'Malo kvasa prekvasi celotno gmoto.',
        10: 'Po Gospodu imam zaupanje v vas, da ne boste drugače misleči; toda kdor vas nadleguje, bo nosil svojo obsodbo, kdorkoli bo.',
        11: 'In jaz, bratje, če vendarle oznanjam obrezo, zakaj še vedno trpim preganjanje? Potem je pohujšanje križa prenehalo.',
        12: 'Kateri pa vas begajo, želim, da bi bili celó odrezani.',
        13: 'Kajti bratje, poklicani ste bili v svobodo; samo svobode ne uporabite za priložnost mesu, temveč v ljubezni služite drug drugemu.',
        14: 'Kajti vsa postava je izpolnjena v eni besedi, celó v tej: ›Svojega bližnjega boš ljubil kakor samega sebe.‹',
        15: 'Toda če drug drugega grizete in hrustate, pazite, da ne boste požrti eden od drugega.',
        16: 'Pravim torej to: »Hodite v Duhu in ne boste uresničili poželenja mesa.«',
        17: 'Kajti meso hrepeni zoper Duha, Duh pa zoper meso; in ta dva sta drug drugemu nasprotna, tako da ne morete delati stvari, ki bi jih želeli.',
        18: 'Toda če ste vodeni od Duha, niste pod postavo.',
        19: '§ Torej dela mesa so očitna, ki so ta: zakonolomstvo, prešuštvovanje, nečistost, pohotnost,',
        20: 'malikovanje, čaranje, sovraštvo, prerekanje, tekmovanja, bes, prepir, upori, krivoverstva,',
        21: 'zavisti, umori, pijanost, veseljačenja in podobno; o katerih vam vnaprej povem, kakor sem vam tudi povedal v preteklem času, da tisti, ki počenjajo takšne stvari, ne bodo podedovali Božjega kraljestva.',
        22: 'Toda sad Duha je ljubezen, radost, mir, potrpežljivost, blagost, dobrota, vera,',
        23: 'krotkost, zmernost; zoper te ni postave.',
        24: 'In tisti, ki so Kristusovi, so meso križali s strastmi in poželenji.',
        25: 'Če živimo po Duhu, tudi hodimo v Duhu.',
        26: 'Ne bodimo željni prazne slave z izzivanjem drug drugega in zavidanjem drug drugemu.',
    },
    6: {
        1: '§ Bratje, če je človek zasačen v krivdi, vi, ki ste duhovni, obnovite takšnega v duhu krotkosti; in se opazujte, da ne bi bili tudi vi skušani.',
        2: 'Nosite bremena drug drugemu in tako izpolnite Kristusovo postavo.',
        3: 'Kajti če človek misli, da je on sam kaj, ko ni nič, samega sebe zavaja.',
        4: '§ Toda vsakdo naj preizkusi svoje lastno delo in potem bo imel veselje le v sebi in ne v drugem.',
        5: 'Kajti vsak človek bo nosil svoje lastno breme.',
        6: 'Kdor je poučevan v besedi, naj vse dobrine deli s tistim, ki poučuje.',
        7: 'Ne bodite zavedeni; Bog se ne [pusti] zasmehovati; kajti karkoli človek seje, to bo tudi žel.',
        8: 'Kajti kdor seje v svoje meso, bo od mesa požel trohljivost; toda kdor seje v Duha, bo od Duha požel večno življenje.',
        9: 'In ne bodimo naveličani v izvrševanju dobrega, kajti če ne izgubimo poguma, bomo v pravšnjem obdobju želi.',
        10: 'Medtem ko imamo torej priložnost, delajmo dobro vsem ljudem, še posebej tem, ki so iz verne družine.',
        11: '§ Poglejte kako veliko pismo sem vam napisal s svojo lastno roko.',
        12: 'Kolikor jih želi storiti dober prikaz v mesu, vas silijo, da bi bili obrezani; samo da oni ne bi trpeli preganjanja zaradi Kristusovega križa.',
        13: 'Kajti niti oni sami, ki so obrezani, se ne držijo postave; temveč vas želijo imeti obrezane, da bi se lahko ponašali z vašim mesom.',
        14: 'Toda Bog ne daj, da bi se jaz ponašal, razen s križem našega Gospoda Jezusa Kristusa, po katerem je svet križan meni, jaz pa svetu.',
        15: '§ Kajti v Kristusu Jezusu niti obreza ne koristi nič niti neobreza, temveč novo ustvarjeno bitje.',
        16: 'In kateri živijo glede na to pravilo, mir bodi nad njimi in usmiljenje in nad Božjim Izraelom.',
        17: 'Odslej naj me noben človek ne vznemirja, kajti na svojem telesu nosim znamenja Gospoda Jezusa.',
        18: 'Bratje, milost našega Gospoda Jezusa Kristusa bodi z vašim duhom. Amen. [Galačanom, napisano iz Rima.]',
    },
}
